#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <string>
#include <stdexcept>

namespace RISC_V {

class InstructionBase {
public:
    enum Type { R_TYPE, I_TYPE, S_TYPE, B_TYPE, U_TYPE, J_TYPE };

    unsigned opcode;
    unsigned rs1, rs2, rd;
    Immediate imm;
    Instruction inst;
    enum Type t;

    InstructionBase();
    InstructionBase(unsigned);
    static InstructionBase nop();
    bool is_nop();
    static constexpr unsigned int bin_mask(int digits);
    static unsigned int get_digits(unsigned int n, int hi, int lo);
    static unsigned int expand_digit(unsigned int digit, int lo);
    bool is_valid(const std::string &key);
    void verify(const std::string &key);
    void debug();
    bool has_op1();
    bool has_op2();
};

InstructionBase::InstructionBase()
    : opcode(0), rs1(0), rs2(0), rd(0), imm(0), inst(0), t(R_TYPE) {}

InstructionBase::InstructionBase(unsigned op)
    : opcode(op & bin_mask(7)), rs1((op >> 15) & bin_mask(5)), rs2((op >> 20) & bin_mask(5)), rd((op >> 7) & bin_mask(5)), imm(0), inst(op), t(I_TYPE) {}

InstructionBase InstructionBase::nop() {
    return InstructionBase(0x13);
}

bool InstructionBase::is_nop() {
    return opcode == 0x13 && rd == 0 && rs1 == 0 && rs2 == 0;
}

constexpr unsigned int InstructionBase::bin_mask(int digits) {
    return (1 << digits) - 1;
}

unsigned int InstructionBase::get_digits(unsigned int n, int hi, int lo) {
    return (n >> lo) & bin_mask(hi - lo + 1);
}

unsigned int InstructionBase::expand_digit(unsigned int digit, int lo) {
    if ((digit & (1 << lo)) != 0)
        return digit | (~bin_mask(lo));
    else
        return digit;
}

bool InstructionBase::is_valid(const std::string &key) {
    if (key == "opcode") return true;
    if (key == "rs1" && t != U_TYPE && t != J_TYPE) return true;
    if (key == "rs2" && (t == R_TYPE || t == S_TYPE || t == B_TYPE)) return true;
    if (key == "rd" && t != I_TYPE && t != S_TYPE && t != B_TYPE && t != U_TYPE) return true;
    if (key == "imm") return true;
    return false;
}

void InstructionBase::verify(const std::string &key) {
    if (!is_valid(key))
        throw std::invalid_argument("Invalid key access: " + key);
}

void InstructionBase::debug() {
    switch (t) {
        case R_TYPE:
            std::cout << "R-type instruction: rd=" << rd << ", rs1=" << rs1 << ", rs2=" << rs2 << std::endl;
            break;
        case I_TYPE:
            std::cout << "I-type instruction: rd=" << rd << ", rs1=" << rs1 << ", imm=" << imm << std::endl;
            break;
        case S_TYPE:
            std::cout << "S-type instruction: rs1=" << rs1 << ", rs2=" << rs2 << ", imm=" << imm << std::endl;
            break;
        case B_TYPE:
            std::cout << "B-type instruction: rs1=" << rs1 << ", rs2=" << rs2 << ", imm=" << imm << std::endl;
            break;
        case U_TYPE:
            std::cout << "U-type instruction: rd=" << rd << ", imm=" << imm << std::endl;
            break;
        case J_TYPE:
            std::cout << "J-type instruction: rd=" << rd << ", imm=" << imm << std::endl;
            break;
    }
}

bool InstructionBase::has_op1() {
    return t != U_TYPE && t != J_TYPE;
}

bool InstructionBase::has_op2() {
    return (t == R_TYPE || t == S_TYPE || t == B_TYPE);
}

class InstructionR : public InstructionBase {
public:
    InstructionR(const Instruction &inst);
};

InstructionR::InstructionR(const Instruction &inst)
    : InstructionBase(inst) {}

class InstructionI : public InstructionBase {
public:
    InstructionI(const Instruction &inst);
};

InstructionI::InstructionI(const Instruction &inst)
    : InstructionBase(inst) {}

class InstructionS : public InstructionBase {
public:
    InstructionS(const Instruction &inst);
};

InstructionS::InstructionS(const Instruction &inst)
    : InstructionBase(inst) {}

class InstructionB : public InstructionBase {
public:
    InstructionB(const Instruction &inst);
};

InstructionB::InstructionB(const Instruction &inst)
    : InstructionBase(inst) {}

class InstructionU : public InstructionBase {
public:
    InstructionU(const Instruction &inst);
};

InstructionU::InstructionU(const Instruction &inst)
    : InstructionBase(inst) {}

class InstructionJ : public InstructionBase {
public:
    InstructionJ(const Instruction &inst);
};

InstructionJ::InstructionJ(const Instruction &inst)
    : InstructionBase(inst) {}

}

#endif // INSTRUCTION_HPP
